p -= vec2(1.5, .8660254);
c = min(c, dot(p, p));
p -= vec2( 0.0 , -1.73205);
c = min(c, dot(p, p));
return sqrt(c);
}
float map(vec3 p){
float c = heightMap(p.xy);
// Height map.
c = cos(c*6.2831589) + cos(c*6.2831589*2.);
c = (clamp(c*.6 +.5, 0., 1.));
return 1. - p.z - c*.025;
