edge *= (int)vis_version > 2 ? 1.0 * vis_intensity+vis_shift : (1.1-0.2*smoothstep( 0.0 , 2.0 ,(int)vis_version == 1 ? bass_smooth : audioLowSmooth))*vis_intensity+vis_shift;
#else
edge *= 1.05-0.1*smoothstep( 0.0 , 2.0 ,audioLowSmooth);
#endif
