e = vec2(.0025, 0.0 );
d1 = map(p + e.xyy), d2 = map(p - e.xyy);
d3 = map(p + e.yxy), d4 = map(p - e.yxy);
d5 = map(p + e.yyx), d6 = map(p - e.yyx);
