#ifdef bass_smooth
float fac = (0.85+0.3*smoothstep( 0.0 , 2.0 ,bass_smooth))*vis_intensity+vis_shift;
#else
float fac = 0.95+0.1*smoothstep( 0.0 , 2.0 ,audioLowSmooth);
#endif
c = smoothstep(.4, 1., c*fac);
// Darken and add contast for more of a spotlight look.
vec3 col = vec3(c, c*c, c*c*c*c);
