return fract(vec2( 262144.0 , 32768.0 )*n)*.75 + .25;
}
float Voronoi(in vec2 p){
vec2 g = floor(p), o; p -= g;
vec3 d = vec3( 1.0 , 1.0 , 1.0 );
// 1.4, etc. "d.z" holds the distance comparison value.
for(int y = -1; y <= 1; y++){
for(int x = -1; x <= 1; x++){
o = vec2(x, y);
o += hash22(g + o) - p;
d.z = dot(o, o);
d.y = max(d.x, min(d.y, d.z));
d.x = min(d.x, d.z);
}
}
return max(d.y/1.2 - d.x*1., 0.)/1.2;
}
// Edge and curve value. Passed into, and set, during the normal calculation.
float edge=0, crv=0;
// Surface postion, surface normal and light direction.
vec3 sp = ro + rd*t;
vec3 sn = getNormal(sp, edge, crv);
vec3 ld = lp - sp;
// Coloring and texturing the surface.
//
// Height map.
float c = heightMap(sp.xy);
// Folding, or wrapping, the values above to produce the snake-like pattern that lines up with the randomly
// flipped hex cells produced by the height map.
vec3 fold = cos(vec3( 1.0 , 2.0 , 4.0 )*c*6.2831589);
// Using the height map value, then wrapping it, to produce a finer grain Truchet pattern for the overlay.
float c2 = heightMap((sp.xy + sp.z*.025)*6.);
c2 = cos(c2*6.2831589*3.);
c2 = (clamp(c2 +.5, 0., 1.));
// Function based bump mapping. I prefer none in this example, but it's there if you want it.
//if(temp.x>0. || temp.y>0.) sn = dbF(sp, sn, .001);
// Surface color value.
vec3 oC = vec3( 1.0 , 1.0 , 1.0 );
if(fold.x>0.) oC = vec3( 1.0 , .05, .1)*c2;
// Reddish pink with finer grained Truchet overlay.
if(fold.x<0.05 && (fold.y)<0.) oC = vec3( 1.0 , .7, .45)*(c2*.25 + .75);
// Lighter lined borders.
else if(fold.x<0.) oC = vec3( 1.0 , .8, .4)*c2;
// Gold, with overlay.
// oC *= n3D(sp*128.)*.35 + .65; // Extra fine grained noisy texturing.
// Sending some greenish particle pulses through the snake-like patterns. With all the shininess going
// on, this effect is a little on the subtle side.
float p1 = 1.0 - smoothstep(0., .1, fold.x*.5+.5);
// Restrict to the snake-like path.
// Other path.
// float p2 = 1.0 - smoothstep(0., .1, cos(heightMap(sp.xy + 1. + uTime/4.)*6.283)*.5+.5);
float p2 = 1.0 - smoothstep(0., .1, Voronoi(sp.xy*4. + vec2(tm, cos(tm/4.))));
p1 = (p2 + .25)*p1;
// Overlap the paths.
oC += oC.yxz*p1*p1;
// Gives a kind of electron effect. Works better with just Voronoi, but it'll do.
float lDist = max(length(ld), 0.001);
// Light distance.
float atten = 1./(1. + lDist*.125);
// Light attenuation.
ld /= lDist;
// Normalizing the light direction vector.
float diff = max(dot(ld, sn), 0.);
// Diffuse.
float spec = pow(max( dot( reflect(-ld, sn), -rd ), 0.0 ), 16.);
// Specular.
float fre = pow(clamp(dot(sn, rd) + 1., .0, 1.), 3.);
// Fresnel, for some mild glow.
// Shading. Note, there are no actual shadows. The camera is front on, so the following
// two functions are enough to give a shadowy appearance.
crv = crv*.9 + .1;
// Curvature value, to darken the crevices.
float ao = calculateAO(sp, sn);
// Ambient occlusion, for self shadowing.
// Combining the terms above to light the texel.
vec3 col = oC*(diff + .5) + vec3(1., .7, .4)*spec*2. + vec3(.4, .7, 1.0 )*fre;
col += (oC*.5+.5)*envMap(reflect(rd, sn), sn)*6.;
// Fake environment mapping.
// Edges.
col *= 1. - edge*.85;
// Darker edges.
// Applying the shades.
col *= (atten*crv*ao);
// Rough gamma correction, then present to the screen.
fragColor = vec4(sqrt(clamp(col, 0., 1.)), 1.);
ret = fragColor;
}
shader_body {
vec4 fragColor = 0;
// CONV: Center on screen, then try some uAspect correction
// uv = (uv * 2.0) - 1.0;
vec2 fragCoord  = uv;
fragCoord.y -= 0.2;
uv.y += 0.5;
uv.x += 0.5;
// uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
// uv = vec2(uv.x, -uv.y);
// Unit directional ray - Coyote's observation.
vec3 rd = normalize(vec3(3.*fragCoord - uv.xy, uv.y));
float tm = uTime/2.;
// Rotate the XY-plane back and forth. Note that sine and cosine are kind of rolled into one.
float fac = sin(uTime*0.11)*0.4+1.2;
vec2 a = sin(vec2(1.570796, 0.0 ) + sin(tm/4.)*.3);
// Fabrice's observation.
rd.xy = multiply(transpose(mat2(a, -a.y, a.x)),rd.xy);
// Ray origin. Moving in the X-direction to the right.
vec3 ro = 0.1*fac*vec3(tm, cos(tm/4.), 0.5);
// Light position, hovering around behind the camera.
vec3 lp = ro + vec3(cos(tm/2.)*.5, sin(tm/2.)*.5, -.5);
// Standard raymarching segment. Because of the straight forward setup, not many iterations are necessary.
float d, t=0.;
for(int j=0;j<LOOPS;j++){
d = map(ro + rd*t);
// distance to the function.
t += d*.7;
// Total distance from the camera to the surface.
// The plane "is" the far plane, so no "far = plane" break is needed.
// CONV: break unsupported, see Milkwave manual
if(d<0.001) j=LOOPS;
}
